-- The SOLIDMILL code key (Code keys -> Milling -> SOLIDMILL), from the ISCAR
-- e-catalog's SOLIDMILL families; kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.solidmill', $ck${"title": "SOLIDMILL code key – solid carbide endmills (Premium, TEC and Ceramic lines)", "subtitle": "Solid carbide square, ball nose, toroidal, chamfering, corner rounding, composite and economical (TEC) endmills, and solid ceramic endmills", "example": "EC-A4 08-20C08R.5E63", "decoder": "solidmill", "sections": [{"key": "t-family", "title": "Tool – family", "sample": "EC", "rows": [{"code": "EC", "meaning": "Endmill"}, {"code": "ECC", "meaning": "Endmill with chamfered corners"}, {"code": "ECCS", "meaning": "Short slot drill endmill with a relieved neck and chamfered corners"}, {"code": "ECS", "meaning": "Short slot drill endmill with a relieved neck"}, {"code": "ECL", "meaning": "Long endmill"}, {"code": "ECXL", "meaning": "Extra long endmill"}, {"code": "ECH", "meaning": "Endmill for finishing hard materials (up to 65 HRC)"}, {"code": "ECA", "meaning": "Endmill for machining aluminum"}, {"code": "ECU", "meaning": "Undersized slot drill endmill for keyways (DIN 6885)"}, {"code": "ECT", "meaning": "Tapered endmill for hardened steel"}, {"code": "ECF", "meaning": "Chamfering and countersinking endmill"}, {"code": "EB", "meaning": "Ball nose endmill"}, {"code": "EBL", "meaning": "Long ball nose endmill"}, {"code": "EBM", "meaning": "Miniature ball nose endmill"}, {"code": "EBA", "meaning": "High precision ball nose endmill for aluminum"}, {"code": "ESB", "meaning": "Spherical long ball nose endmill (up to 65 HRC)"}, {"code": "ETR", "meaning": "Toroidal endmill"}, {"code": "ER", "meaning": "Corner rounding endmill"}, {"code": "EPN", "meaning": "Endmill for composite materials"}, {"code": "EPNF", "meaning": "Endmill for composite materials"}, {"code": "EPNC", "meaning": "Endmill with special cutting edges for composite materials"}, {"code": "EPND", "meaning": "Endmill with special cutting edges, also for drill milling"}, {"code": "EPX", "meaning": "Endmill with right- and left-hand helix flutes (composites)"}]}, {"key": "t-helix", "title": "Helix", "rows": [{"code": "A", "meaning": "30° helix"}, {"code": "B", "meaning": "45° helix"}, {"code": "C", "meaning": "Geometry C (composite materials) (see the catalog)"}, {"code": "D", "meaning": "50° helix (hardened steel)"}, {"code": "E", "meaning": "38° helix"}, {"code": "F", "meaning": "55° helix (aluminum); composite geometry on EPN / EPX (see the catalog)"}, {"code": "S", "meaning": "Geometry S (see the catalog)"}]}, {"key": "t-flutes", "title": "Number of flutes", "rows": [{"code": "#", "meaning": "Number of flutes"}, {"code": "##", "meaning": "Number of flutes"}]}, {"key": "t-dims", "title": "Geometry / dimension code", "rows": [{"code": "…", "meaning": "Further code (see the catalog)"}]}, {"key": "t-dia", "title": "Cutting diameter", "rows": [{"code": "##", "meaning": "Diameter in mm"}, {"code": "###", "meaning": "Diameter x10 (compact designations) or mm with decimals (015 = 1.5 mm)"}]}, {"key": "t-apmx", "title": "Cutting length", "rows": [{"code": "##", "meaning": "Cutting length in mm"}]}, {"key": "t-neck", "title": "Neck (reach) length", "rows": [{"code": "/##", "meaning": "Length to the neck end in mm"}]}, {"key": "t-taper", "title": "Taper", "rows": [{"code": "/#.#", "meaning": "Taper angle per side"}]}, {"key": "t-angle", "title": "Chamfer angle", "rows": [{"code": "##", "meaning": "Chamfer angle"}]}, {"key": "s-shank", "title": "Shank type", "rows": [{"code": "C", "meaning": "Cylindrical shank"}, {"code": "W", "meaning": "Weldon shank"}]}, {"key": "s-dia", "title": "Shank diameter", "rows": [{"code": "##", "meaning": "Shank diameter in mm"}]}, {"key": "t-corner", "title": "Corner", "rows": [{"code": "R#.#", "meaning": "Corner radius in mm"}, {"code": "R##", "meaning": "Corner radius x10 (R02 = 0.2 mm)"}, {"code": "RP#.#", "meaning": "Programmed radius (Rg) for CAM"}]}, {"key": "t-line", "title": "Line (before the overall length)", "rows": [{"code": "E", "meaning": "Economical line (TEC)"}, {"code": "F", "meaning": "For composite materials"}, {"code": "H", "meaning": "For hard materials (see the catalog)"}, {"code": "M", "meaning": "Line M (see the catalog)"}, {"code": "N", "meaning": "For nickel based alloys, cast iron and graphite (ceramic)"}]}, {"key": "t-oal", "title": "Overall length", "rows": [{"code": "##", "meaning": "Overall length in mm"}, {"code": "###", "meaning": "Overall length in mm"}]}, {"key": "t-suffix", "title": "Suffix", "rows": [{"code": "CE", "meaning": "Solid ceramic endmill"}, {"code": "D", "meaning": "Version D (see the catalog)"}, {"code": "T", "meaning": "Version T (see the catalog)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
